import{_ as a,o as e,c as n,ak as i}from"./chunks/framework.DJ-92fJv.js";const u=JSON.parse('{"title":"⏸️ 挂起/恢复学生端进程","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"features/suspend-student.md","filePath":"features/suspend-student.md"}'),t={name:"features/suspend-student.md"};function l(r,s,o,p,d,h){return e(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="⏸️-挂起-恢复学生端进程" tabindex="-1">⏸️ 挂起/恢复学生端进程 <a class="header-anchor" href="#⏸️-挂起-恢复学生端进程" aria-label="Permalink to “⏸️ 挂起/恢复学生端进程”">​</a></h1><p><strong>主菜单选项：<code>8</code></strong></p><p>挂起（Suspend）与终止（Kill）不同：挂起是<strong>暂停进程的运行</strong>而不关闭它，进程仍在内存中但<strong>不执行任何操作</strong>。这比直接终止更隐蔽，学生端管理系统可能检测不到异常。</p><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to “工作原理”">​</a></h2><p>脚本使用 PowerShell 调用 Windows API 来实现进程的挂起和恢复：</p><h3 id="挂起-suspend" tabindex="-1">挂起（Suspend） <a class="header-anchor" href="#挂起-suspend" aria-label="Permalink to “挂起（Suspend）”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Student.exe（运行中）──调用 Suspend()──→ Student.exe（已挂起）</span></span>
<span class="line"><span>                                           - 进程在内存中，但不执行代码</span></span>
<span class="line"><span>                                           - 学生端管理功能暂停工作</span></span>
<span class="line"><span>                                           - 老师端可能显示&quot;在线&quot;但无法控制</span></span></code></pre></div><h3 id="恢复-resume" tabindex="-1">恢复（Resume） <a class="header-anchor" href="#恢复-resume" aria-label="Permalink to “恢复（Resume）”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Student.exe（已挂起）──调用 Resume()──→ Student.exe（运行中）</span></span>
<span class="line"><span>                                        - 进程恢复正常运行</span></span>
<span class="line"><span>                                        - 学生端管理功能恢复</span></span></code></pre></div><h2 id="执行流程" tabindex="-1">执行流程 <a class="header-anchor" href="#执行流程" aria-label="Permalink to “执行流程”">​</a></h2><ol><li>脚本首先检测 <code>Student.exe</code> 是否存在，不存在则提示并返回</li><li>检测当前状态： <ul><li><strong>如果已挂起</strong> → 自动执行<strong>恢复</strong>操作</li><li><strong>如果运行中</strong> → 准备执行<strong>挂起</strong>操作</li></ul></li><li>挂起操作包含窗口最小化/恢复的自动化过程</li></ol><h2 id="挂起的详细步骤" tabindex="-1">挂起的详细步骤 <a class="header-anchor" href="#挂起的详细步骤" aria-label="Permalink to “挂起的详细步骤”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>选择挂起 →</span></span>
<span class="line"><span>  5秒倒计时（可跳过）→</span></span>
<span class="line"><span>  窗口将在2秒后最小化 →</span></span>
<span class="line"><span>  后台执行挂起操作 →</span></span>
<span class="line"><span>  [√] Student.exe 已挂起 →</span></span>
<span class="line"><span>  自动恢复窗口</span></span></code></pre></div><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to “使用场景”">​</a></h2><ul><li>✅ <strong>不想被老师发现异常</strong> — 挂起比终止更隐蔽</li><li>✅ <strong>想临时自由活动</strong> — 挂起后恢复，不留痕迹</li><li>✅ <strong>需要时再恢复</strong> — 随时可以恢复学生端正常运行</li><li>✅ <strong>避免进程保护机制</strong> — 某些版本对终止有保护，挂起可以绕过</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><ul><li>挂起功能<strong>只针对 <code>Student.exe</code></strong>，不影响其他学生端进程</li><li>挂起后学生端进程仍在任务管理器中可见，但状态显示为&quot;已挂起&quot;</li><li>如需解除所有限制，建议使用 <strong>一键解锁</strong></li></ul></div>`,17)])])}const g=a(t,[["render",l]]);export{u as __pageData,g as default};
